type Options struct {
	Width  int
	Border bool
}

func render(text string, opts Options) string {
	if opts.Width == 0 {
		opts.Width = 12 // standart kenglik
	}
	line := fmt.Sprintf("%-*s", opts.Width, text)
	if opts.Border {
		return "[" + line + "]"
	}
	return line + "|"
}

func main() {
	fmt.Println(render("Salom", Options{}))
	fmt.Println(render("Salom", Options{Width: 8}))
	fmt.Println(render("Salom", Options{Width: 8, Border: true}))
}

