const vatRate = 0.12

func lineTotal(price float64, qty int) float64 {
	return price * float64(qty)
}

func applyDiscount(amount, percent float64) float64 {
	return amount * (1 - percent/100)
}

func addVAT(amount float64) float64 {
	return amount * (1 + vatRate)
}

func main() {
	subtotal := lineTotal(12500, 3) + lineTotal(8000, 2)
	discounted := applyDiscount(subtotal, 10)
	total := addVAT(discounted)
	fmt.Printf("Jami: %.2f\n", subtotal)
	fmt.Printf("Chegirmadan keyin: %.2f\n", discounted)
	fmt.Printf("QQS bilan: %.2f\n", total)
}

