import "fmt"

func gcd(a, b int) int {
	for b != 0 {
		a, b = b, a%b
	}
	return a
}

func lcm(a, b int) int {
	return a / gcd(a, b) * b
}

func main() {
	fmt.Println("EKUB(48, 18) =", gcd(48, 18))
	fmt.Println("EKUB(17, 5) =", gcd(17, 5))
	fmt.Println("EKUK(4, 6) =", lcm(4, 6))
}

