import "fmt"

func minMax(nums []int) (int, int) {
	lo, hi := nums[0], nums[0]
	for _, n := range nums[1:] {
		if n < lo {
			lo = n
		}
		if n > hi {
			hi = n
		}
	}
	return lo, hi
}

func main() {
	lo, hi := minMax([]int{7, -3, 12, 5, 0})
	fmt.Println("eng kichik:", lo)
	fmt.Println("eng katta:", hi)
