func summarize(nums []float64) (float64, float64, float64) {
	lo, hi, sum := nums[0], nums[0], 0.0
	for _, n := range nums {
		lo = min(lo, n)
		hi = max(hi, n)
		sum += n
	}
	return lo, hi, sum / float64(len(nums))
}

func main() {
	lo, hi, avg := summarize([]float64{72.5, 88, 95.5, 64})
	fmt.Printf("min=%.1f max=%.1f o'rtacha=%.1f\n", lo, hi, avg)
}

