import "fmt"

type Stats struct {
	Min, Max int
	Avg      float64
}

func analyze(nums []int) Stats {
	s := Stats{Min: nums[0], Max: nums[0]}
	total := 0
	for _, n := range nums {
		s.Min = min(s.Min, n)
		s.Max = max(s.Max, n)
		total += n
	}
	s.Avg = float64(total) / float64(len(nums))
	return s
}

func main() {
	stats := analyze([]int{4, 8, 15, 16, 23, 42})
	fmt.Printf("%+v\n", stats)
	fmt.Println("farq:", stats.Max-stats.Min)
}

