import "fmt"

type Stack struct {
	Push func(int)
	Pop  func() (int, bool)
	Len  func() int
}

func NewStack() Stack {
	var items []int
	return Stack{
		Push: func(v int) { items = append(items, v) },
		Pop: func() (int, bool) {
			if len(items) == 0 {
				return 0, false
			}
			v := items[len(items)-1]
			items = items[:len(items)-1]
			return v, true
		},
		Len: func() int { return len(items) },
	}
}

func main() {
	s := NewStack()
	s.Push(10)
	s.Push(20)
	s.Push(30)
	fmt.Println("uzunlik:", s.Len())

	for range 4 {
		v, ok := s.Pop()
		fmt.Println(v, ok)
	}
}

