import "fmt"

type stateFn func(*machine) stateFn

type machine struct {
	input string
	pos   int
	words []string
}

func lexStart(m *machine) stateFn {
	if m.pos >= len(m.input) {
		return nil
	}
	if m.input[m.pos] == ' ' {
		m.pos++
		return lexStart
	}
	return lexWord
}

func lexWord(m *machine) stateFn {
	start := m.pos
	for m.pos < len(m.input) && m.input[m.pos] != ' ' {
		m.pos++
	}
	m.words = append(m.words, m.input[start:m.pos])
	return lexStart
}

func main() {
	m := &machine{input: "  go  tilida   holat funksiyalari "}

	for state := stateFn(lexStart); state != nil; {
		state = state(m)
	}
	fmt.Printf("%q\n", m.words)
}

