func binarySearch(a []int, target, lo, hi int) int {
	if lo > hi {
		return -1
	}
	mid := lo + (hi-lo)/2
	switch {
	case a[mid] == target:
		return mid
	case a[mid] < target:
		return binarySearch(a, target, mid+1, hi)
	default:
		return binarySearch(a, target, lo, mid-1)
	}
}

func main() {
	sorted := []int{2, 5, 8, 12, 16, 23, 38, 56, 72, 91}

	fmt.Println(binarySearch(sorted, 23, 0, len(sorted)-1))
	fmt.Println(binarySearch(sorted, 91, 0, len(sorted)-1))
	fmt.Println(binarySearch(sorted, 40, 0, len(sorted)-1))
}

