func render(name string, v any, depth int) {
	pad := strings.Repeat("  ", depth)
	switch x := v.(type) {
	case map[string]any:
		fmt.Printf("%s%s:\n", pad, name)
		keys := make([]string, 0, len(x))
		for k := range x {
			keys = append(keys, k)
		}
		sort.Strings(keys)
		for _, k := range keys {
			render(k, x[k], depth+1)
		}
	case []any:
		fmt.Printf("%s%s: (%d ta)\n", pad, name, len(x))
		for i, item := range x {
			render(fmt.Sprintf("[%d]", i), item, depth+1)
		}
	default:
		fmt.Printf("%s%s = %v\n", pad, name, x)
	}
}

func main() {
	config := map[string]any{
		"name": "demo",
		"server": map[string]any{
			"host": "localhost",
			"port": 8080,
		},
		"tags": []any{"go", "backend"},
	}
	render("config", config, 0)
}

