type Tree struct {
	Value       int
	Left, Right *Tree
}

func insert(t *Tree, v int) *Tree {
	if t == nil {
		return &Tree{Value: v}
	}
	if v < t.Value {
		t.Left = insert(t.Left, v)
	} else {
		t.Right = insert(t.Right, v)
	}
	return t
}

func inOrder(t *Tree, visit func(int)) {
	if t == nil {
		return
	}
	inOrder(t.Left, visit)
	visit(t.Value)
	inOrder(t.Right, visit)
}

func main() {
	var root *Tree
	for _, v := range []int{50, 30, 70, 20, 40, 60, 80} {
		root = insert(root, v)
	}

	inOrder(root, func(v int) { fmt.Print(v, " ") })
	fmt.Println()
}

