import "fmt"

func solve(row, n int, cols, d1, d2 []bool) int {
	if row == n {
		return 1
	}
	count := 0
	for c := 0; c < n; c++ {
		if cols[c] || d1[row+c] || d2[row-c+n-1] {
			continue
		}
		cols[c], d1[row+c], d2[row-c+n-1] = true, true, true
		count += solve(row+1, n, cols, d1, d2)
		cols[c], d1[row+c], d2[row-c+n-1] = false, false, false
	}
	return count
}

func main() {
	for _, n := range []int{4, 6, 8} {
		cols := make([]bool, n)
		d1 := make([]bool, 2*n-1)
		d2 := make([]bool, 2*n-1)
		fmt.Printf("%d farzin: %d ta yechim\n", n, solve(0, n, cols, d1, d2))
	}
}

