func quickSort(a []int) []int {
	if len(a) <= 1 {
		return a
	}
	pivot := a[0]
	var less, more []int
	for _, v := range a[1:] {
		if v <= pivot {
			less = append(less, v)
		} else {
			more = append(more, v)
		}
	}
	result := append(quickSort(less), pivot)
	return append(result, quickSort(more)...)
}

