import "fmt"

type Node struct {
	Name     string
	Children []*Node
}

func walkRecursive(n *Node) []string {
	order := []string{n.Name}
	for _, c := range n.Children {
		order = append(order, walkRecursive(c)...)
	}
	return order
}

func walkIterative(root *Node) []string {
	var order []string
	stack := []*Node{root}
	for len(stack) > 0 {
		n := stack[len(stack)-1]
		stack = stack[:len(stack)-1]
		order = append(order, n.Name)
		for i := len(n.Children) - 1; i >= 0; i-- {
			stack = append(stack, n.Children[i])
		}
	}
	return order
}

func main() {
	tree := &Node{"A", []*Node{
		{"B", []*Node{{"D", nil}, {"E", nil}}},
		{"C", []*Node{{"F", nil}}},
	}}

	fmt.Println("rekursiv:", walkRecursive(tree))
	fmt.Println("sikl+stek:", walkIterative(tree))
}

